/* Impulso: reusable fitness module. Data writes go through FitnessStore. */
(() => {
  'use strict';
  const C = window.FitnessCore, Store = window.FitnessStore, IO = window.FitnessIO, Plan = window.FitnessWorkoutPlan;
  const $ = s => document.querySelector(s), esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const id = () => crypto.randomUUID(), clone = v => JSON.parse(JSON.stringify(v));
  const day = (d = new Date()) => { const t = new Date(d); return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`; };
  const num = v => Number(v) || 0, fmt = (v,d=0) => Number(v||0).toLocaleString('es-PA',{maximumFractionDigits:d});
  const dateText = d => new Date(`${String(d).slice(0,10)}T12:00:00`).toLocaleDateString('es-PA',{day:'numeric',month:'short',year:'numeric'});
  const duration = s => `${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
  const weekDays = ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
  let state, view='hoy', month=day().slice(0,7), mediaURLs=[], toastTimer, editingRoutine;
  function notice(text) { if($('#modal').open){let feedback=$('#modal-feedback');if(!feedback){feedback=document.createElement('p');feedback.id='modal-feedback';feedback.className='source-note';feedback.setAttribute('role','status');$('#modal-body').prepend(feedback);}feedback.textContent=text;feedback.scrollIntoView({block:'nearest'});} $('#toast').textContent=text; $('#toast').hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').hidden=true,5000); }
  function save() { try { Store.save(state); $('#save-status').textContent='Guardado en este dispositivo'; } catch(error) { $('#save-status').textContent='Cambios sin guardar'; throw error; } }
  function field(label,name,value='',type='text',attrs='') {return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
  function select(label,name,value,options){return `<label>${esc(label)}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
  const button=(label,action,data='',style='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${data}>${label}</button>`;
  const head=(k,t,sub='')=>`<div class="page-head"><p class="eyebrow">${k}</p><h1>${t}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>`;
  const metric=(v,l)=>`<div class="metric"><strong>${v}</strong><span>${l}</span></div>`;
  const actions=label=>`<div class="modal-actions"><button class="btn primary" type="submit">${label}</button></div>`;
  function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();loadMedia();}
  function close(){ $('#modal').querySelectorAll('video').forEach(v=>v.pause());$('#modal').close(); }
  function seedExercise(e,i){const target=e.target?.match(/(\d+)\s*×\s*(\d+)[–-](\d+)/);return {...e,id:e.id||id(),muscles:e.muscles||e.primary||'',type:e.type||(e.name?.includes('Plancha')?'isometric':'strength'),sets:num(e.sets)||num(target?.[1])||3,repMin:num(e.repMin)||num(target?.[2])||8,repMax:num(e.repMax)||num(target?.[3])||12,restSeconds:e.restSeconds==null&&e.rest==null?90:num(e.restSeconds??e.rest),notes:e.notes||e.technique?.join('\n')||'',incrementKg:num(e.incrementKg)||2.5};}
  function initialize(){
    Store.init('local');state=Store.load();
    for(const [i,r] of FitnessSeeds.routines.entries()) if(!state.routines.some(x=>x.id===r.id)) state.routines.push({...r,days:i===0?[1,3,5]:i===1?[2,5]:[3,6],exercises:r.exercises.map(seedExercise)});
    state.routines=state.routines.map(r=>({...r,days:Array.isArray(r.days)?r.days:[1,3,5],exercises:r.exercises.map(seedExercise)}));
    state.profile ||= {};state.profile.programStart ||= day();state.profile.dietStart ||= day();
    state.selectedRoutine ||= state.config.activeRoutineId || state.routines[0]?.id;state.meals ||= [];state.config ||= {};state.reminderSeen ||= {};
    state.foods=FitnessFoodCatalog.merge(state.foods);state.nutritionDays||=[];
    updateRecovery();save();navigate(location.hash.slice(1)||'hoy');
  }
  function navigate(next){view=['hoy','rutinas','sesion','progreso','comida','perfil'].includes(next)?next:'hoy';document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===(view==='sesion'?'rutinas':view)));location.hash=view;render();window.scrollTo(0,0);}
  function render(){mediaURLs.forEach(URL.revokeObjectURL);mediaURLs=[];$('#view').innerHTML=({hoy:home,rutinas:routines,sesion:session,progreso:progress,comida:food,perfil:profile})[view]();loadMedia();tick();}
  function weightAverage(){const list=state.weights.filter(w=>w.date<=day()&&w.date>=day(new Date().setDate(new Date().getDate()-6)));return {value:list.length?list.reduce((a,w)=>a+num(w.weightKg),0)/list.length:null,count:list.length};}
  function stats(){const days=[...new Set(state.sessions.filter(s=>s.status==='completed').map(s=>s.date||s.day))].sort(),rest=new Set(state.restDays.map(r=>typeof r==='string'?r:r.date));const all=new Set([...days,...rest]);let cursor=new Date(`${day()}T12:00:00`),streak=0;if(!all.has(day(cursor)))cursor.setDate(cursor.getDate()-1);while(all.has(day(cursor))){streak++;cursor.setDate(cursor.getDate()-1);}return {days,rest,streak};}
  function scheduleInfo(){const p=state.profile,add=(d,n)=>{const v=new Date(`${d||day()}T12:00:00`);v.setDate(v.getDate()+n);return day(v);};return {deload:p.deloadStart>day()?p.deloadStart:add(p.lastDeload||p.programStart,7*(p.deloadWeeks||6)),diet:p.dietBreakStart>day()?p.dietBreakStart:add(p.lastDietBreak||p.dietStart,7*(p.dietBreakWeeks||9))};}
  function updateRecovery(){const p=state.profile;if(p.dietPhase==='scheduled_break'&&p.dietBreakStart<=day()&&state.targets){p.dietPhase='break';state.targets.calories=state.targets.tdee;p.calorieTarget=state.targets.tdee;state.targets.carbs=Math.max(0,Math.round((state.targets.tdee-state.targets.protein*4-state.targets.fat*9)/4));state.lastAdjustmentAt=day();} }
  function home(){const s=stats(),avg=weightAverage(),r=state.routines.find(x=>x.id===state.selectedRoutine)||state.routines[0],plan=scheduleInfo();return head('UN DÍA A LA VEZ',`Tu siguiente<br><span class="muted">pequeño avance.</span>`)+`
    <div class="grid two"><section class="card accent hero"><p class="eyebrow">TU CONSTANCIA</p><div class="stats">${metric(`🔥 ${s.streak}`,'días de continuidad')}${metric(s.days.length,'días entrenados')}</div><p>Los descansos registrados protegen tu continuidad. Cada día entrenado cuenta una vez.</p><div class="toolbar">${button('Registrar descanso','rest')}${button('Registrar peso','weight','','primary')}</div></section>
    <section class="card"><p class="eyebrow">HOY · ${dateText(day())}</p><h2>${esc(state.activeSession?'Tienes una sesión en curso':r?.name||'Tu primera rutina')}</h2><p class="muted">${state.activeSession?'Tus series están guardadas. Continúa cuando quieras.':`${r?.exercises.length||0} ejercicios · ${r?.days.map(x=>weekDays[x-1]).join(', ')||''}`}</p>${button(state.activeSession?'Continuar sesión':'Empezar entrenamiento',state.activeSession?'resume':'start',`data-id="${esc(r?.id)}"`,'primary')}</section></div>
    <div class="grid three"><section class="card">${metric(avg.value?`${fmt(avg.value,2)} kg`:'Sin registro','promedio de los últimos 7 días')}<p class="muted">${avg.count} de 7 días registrados</p></section><section class="card">${metric(state.targets?.calories?fmt(state.targets.calories):'Por calcular','kcal de referencia')}<p class="muted">${state.targets?`${fmt(state.targets.protein)} g de proteína`:'Completa tu perfil para calcularlas.'}</p></section><section class="card mint"><h3>Chequeo semanal</h3><p class="muted">Peso, constancia y cómo te sientes.</p>${button('Hacer chequeo','checkin')}</section></div>
    <section class="card"><div class="toolbar"><h2>La próxima decisión</h2>${button('Revisar tendencia','decision')}</div><p class="muted">Las sugerencias requieren al menos 14 días de historial. Nunca se cambia tu objetivo sin que lo apliques.</p></section>
    <section class="card"><h2>Recuperación programada</h2><div class="grid two"><div><p>Descarga · ${dateText(plan.deload)}</p>${button('Iniciar descarga','deload')}${state.profile.deloadStart<=day()&&state.profile.deloadUntil>day()?'<p class="badge">Descarga activa hasta '+dateText(state.profile.deloadUntil)+'</p>':''}</div><div><p>Pausa de dieta · ${dateText(plan.diet)}</p>${button('Planificar pausa','dietbreak')}${state.profile.dietPhase==='break'?'<p class="badge">Pausa activa hasta '+dateText(state.profile.dietBreakUntil)+'</p>'+button('Retomar objetivo anterior','end-break'):''}</div></div><p class="source-note">Fechas orientativas editables en Perfil. No implican que necesites descansar o modificar tu dieta por un dato aislado.</p></section>`;}
  function routines(){return head('ENTRENAR','A tu manera.','Elige una base o construye tu propia rutina.')+`<div class="toolbar">${button('Crear rutina','routine','','primary')}${state.activeSession?button('Continuar sesión','resume'):''}</div><div class="grid two">${state.routines.map(r=>`<article class="card"><p class="eyebrow">${r.days.map(x=>weekDays[x-1]).join(' · ')}</p><h2>${esc(r.name)}</h2><p class="muted">${r.exercises.length} ejercicios · ${esc([...new Set(r.exercises.map(e=>e.muscles))].join(', '))}</p><div class="toolbar">${button('Empezar','start',`data-id="${r.id}"`,'primary')}${button('Editar rutina','routine',`data-id="${r.id}"`)}${button(state.selectedRoutine===r.id?'Split activo':'Usar este split','select',`data-id="${r.id}"`)}</div></article>`).join('')}</div>`;}
  function previous(e){return state.sessions.slice().reverse().flatMap(s=>s.exercises||[]).find(x=>x.id===e.id||x.name===e.name);}
  function progressionText(e){try {const v=C.progression({...e,setsTarget:e.setsTarget||e.sets.length},state.sessions);return typeof v==='string'?v:(v.message||v.reason||'Suma repeticiones dentro de tu rango antes de subir la carga.')+(v.suggestedWeightKg!==null&&v.suggestedReps?.length?' Propuesta: '+fmt(v.suggestedWeightKg,2)+' kg · '+v.suggestedReps.join(' / ')+' reps.':'');}catch{return 'Suma repeticiones dentro de tu rango antes de subir la carga.';}}
  function session(){const a=state.activeSession;if(!a)return head('TU SESIÓN','Todo listo.')+`<section class="card"><p>Selecciona una rutina para empezar.</p>${button('Ver rutinas','nav', 'data-view="rutinas"','primary')}</section>`;return `<div class="page-head"><p class="eyebrow">SESIÓN EN CURSO · <span class="session-clock" data-session-clock>00:00</span></p><h1>${esc(a.routineName)}</h1><p class="muted">Carga total en kg por repetición. Los cambios se guardan al escribir.</p><p class="source-note">N: normal · W: calentamiento · D: dropset · S: biserie.</p>${a.deload?'<p class="badge">Semana de descarga · series reducidas</p>':''}</div><div class="timer-bar" id="rest-bar"><span>Descanso <strong data-rest-clock>00:00</strong></span>${button('+30 s','rest-more')}${button('Terminar descanso','rest-skip')}</div>
    ${a.exercises.map((e,ei)=>`<article class="card exercise" data-e="${ei}"><div class="toolbar"><div><p class="eyebrow">${esc(e.muscles)}</p><h2>${esc(e.name)}</h2></div>${button('Técnica / multimedia','technique',`data-e="${ei}"`)}</div><p class="muted">${e.type==='strength'?`${e.repMin}–${e.repMax} reps · ${esc(progressionText(e))}`:e.type==='isometric'?'Registra segundos por serie. Selecciona el lado si es unilateral.':'Tiempo y distancia se registran por separado del tonelaje.'}</p><div class="set-row set-head"><span>Tipo</span><span class="previous">Anterior</span><span>${e.type==='strength'?'KG':'SEG'}</span><span>${e.type==='strength'?'REPS':'KM / LADO'}</span><span>RPE</span><span>Hecho</span></div>${e.sets.map((s,si)=>setRow(e,s,ei,si)).join('')}<div class="toolbar">${button('Añadir serie','add-set',`data-e="${ei}"`)}${e.type==='strength'&&!a.deload&&C.progression({...e,setsTarget:e.setsTarget},state.sessions).suggestedReps?.length?button('Usar propuesta de progresión','use-progression',`data-e="${ei}"`):''}</div></article>`).join('')}
    <section class="card"><label>Notas de la sesión<textarea data-session-notes maxlength="2000">${esc(a.notes||'')}</textarea></label><div class="toolbar">${button('Terminar y guardar','finish','','primary')}${button('Descartar sesión','discard','','danger')}</div></section>`;}
  function setRow(e,s,ei,si){const prev=previous(e)?.sets?.[si],attrs=`data-e="${ei}" data-s="${si}"`,input=(key,value,min=0,max=9999,step=1)=>`<input aria-label="${esc(e.name)} serie ${si+1} ${key}" data-set="${key}" ${attrs} type="number" min="${min}" max="${max}" step="${step}" value="${esc(value??'')}" ${s.completed?'disabled':''}>`;return `<div class="set-row ${s.completed?'done':''}"><select aria-label="Tipo serie ${si+1}" data-set="type" ${attrs} ${s.completed?'disabled':''}>${[['N',`${si+1} · N`],['W','W · Calentar'],['D','D · Drop'],['S','S · Biserie']].map(([v,l])=>`<option value="${v}" ${s.type===v?'selected':''}>${l}</option>`).join('')}</select><small class="previous muted">${prev?`${fmt(prev.weightKg,1)} × ${prev.reps||prev.durationSeconds+' s'}`:'—'}</small>${e.type==='strength'?input('weightKg',s.weightKg,0,1000,.25)+input('reps',s.reps,1,200):input('durationSeconds',s.durationSeconds,0,86400)+ (e.type==='cardio'?input('distanceKm',s.distanceKm,0,1000,.01):`<select aria-label="Lado serie ${si+1}" data-set="side" ${attrs} ${s.completed?'disabled':''}>${['Ambos','Izquierdo','Derecho'].map(x=>`<option ${s.side===x?'selected':''}>${x}</option>`).join('')}</select>`)}${input('rpe',s.rpe,1,10,.5)}${button(s.completed?'Listo':'Hecho','complete',`${attrs} aria-pressed="${!!s.completed}" aria-label="${s.completed?'Desmarcar':'Completar'} ${esc(e.name)} serie ${si+1}"`,s.completed?'primary':'')}</div>
    <div class="set-extra">${e.type!=='strength'?button(s.timerStartedAt?'Detener cronómetro':'Cronometrar serie','set-timer',attrs):''}<label>RIR ${input('rir',s.rir,0,10)}</label><label>TUT (s) ${input('tutSeconds',s.tutSeconds,0,3600)}</label><label>Descanso (s) ${input('restSeconds',s.restSeconds,0,1800)}</label>${s.type==='S'?`<label>Grupo biserie<input data-set="supersetGroup" ${attrs} value="${esc(s.supersetGroup||'A')}" maxlength="12"></label>`:''}${s.timerStartedAt?`<strong data-set-clock="${ei}|${si}">00:00</strong>`:''}</div>`;}
  function newSet(e){return {id:id(),type:'N',completed:false,weightKg:Plan.initialWeight(e,state.sessions),reps:'',rpe:'',rir:'',tutSeconds:'',durationSeconds:0,restSeconds:e.restSeconds??90,side:'Ambos'};}
  function start(rid){if(state.activeSession){navigate('sesion');return;}const r=state.routines.find(r=>r.id===rid);if(!r?.exercises.length)throw Error('Agrega al menos un ejercicio a la rutina.');state.activeSession={id:id(),date:day(),startedAt:Date.now(),routineId:r.id,routineName:r.name,status:'active',deload:!!(state.profile.deloadStart<=day()&&state.profile.deloadUntil>day()),exercises:r.exercises.map(e=>({...clone(e),setsTarget:num(e.sets)||3,sets:Array.from({length:state.profile.deloadStart<=day()&&state.profile.deloadUntil>day()?Math.max(1,Math.ceil(num(e.sets)/2)):num(e.sets)||3},()=>newSet(e))}))};save();navigate('sesion');}
  function metrics(s){let volume=0,work=0,reps=0,sets=0,seconds=0,cardio=0,rest=0;const muscles=new Set();let done=0;for(const e of s.exercises||[]){const finished=e.sets.filter(s=>s.completed);if(finished.length){done++;String(e.muscles||'').split(',').map(x=>x.trim()).filter(Boolean).forEach(x=>muscles.add(x));}for(const r of finished){sets++;rest+=num(r.actualRestSeconds??r.restSeconds);if(e.type==='strength'){const v=num(r.weightKg)*num(r.reps);volume+=v;if(r.type!=='W')work+=v;reps+=num(r.reps);}else if(e.type==='cardio')cardio+=num(r.durationSeconds);else seconds+=num(r.durationSeconds);}}return {volume,work,reps,sets,seconds,cardio,rest,done,muscles:[...muscles]};}
  function summary(s){const m=metrics(s);modal('Sesión completada',`<p class="eyebrow">${dateText(s.date)}</p><h2>${esc(s.routineName)}</h2><div class="grid two">${metric(`${fmt(m.volume)} kg`,'tonelaje total (kg × reps)')}${metric(duration((s.finishedAt-s.startedAt)/1000),'duración de sesión')}${metric(m.sets,'series completadas')}${metric(m.done,'ejercicios completados')}</div><p>${fmt(m.work)} kg de trabajo · ${m.reps} repeticiones · ${duration(m.cardio)} cardio · ${duration(m.seconds)} isométricos.</p><h3>Músculos trabajados</h3><p>${esc(m.muscles.join(', ')||'Sin especificar')}</p><h3>Descansos entre series</h3>${s.exercises.map(e=>`<div class="list-row"><span>${esc(e.name)}</span><span>${e.sets.filter(x=>x.completed).map(x=>`${num(x.actualRestSeconds??x.restSeconds)} s`).join(' / ')||'Sin series'}</span></div>`).join('')}<p class="source-note">Se muestra el descanso transcurrido cuando se registró; en otros casos, el descanso configurado.</p>${s.notes?`<p>${esc(s.notes)}</p>`:''}<div class="modal-actions">${button('Ver historial','show-history','','primary')}</div>`);}
  function chart(points,label){if(points.length<2)return `<p class="empty">Registra al menos dos datos para ver la gráfica.</p>`;const min=Math.min(...points.map(p=>p[1])),max=Math.max(...points.map(p=>p[1])),span=max-min||1;const xPoint=(p,i)=>{const first=Date.parse(points[0][0]),last=Date.parse(points.at(-1)[0]),stamp=Date.parse(p[0]);return Number.isFinite(first)&&last>first?30+(stamp-first)/(last-first)*540:30+i*540/(points.length-1);};return `<div class="chart"><svg viewBox="0 0 600 170" role="img" aria-label="${esc(label)}"><line x1="30" y1="135" x2="570" y2="135" stroke="#555"/><polyline fill="none" stroke="#ccbbff" stroke-width="3" points="${points.map((p,i)=>`${xPoint(p,i)},${125-(p[1]-min)/span*100}`).join(' ')}"/>${points.map((p,i)=>`<circle cx="${xPoint(p,i)}" cy="${125-(p[1]-min)/span*100}" r="4" fill="#cce899"><title>${esc(p[0])}: ${fmt(p[1],2)}</title></circle>`).join('')}<text x="30" y="165" fill="#aaa" font-size="12">${esc(points[0][0])}</text><text x="570" y="165" text-anchor="end" fill="#aaa" font-size="12">${esc(points.at(-1)[0])}</text><text x="30" y="15" fill="#aaa" font-size="12">${fmt(min,1)} – ${fmt(max,1)}</text></svg></div>`;}
  function calendar(){const [y,m]=month.split('-').map(Number),start=new Date(y,m-1,1),last=new Date(y,m,0).getDate(),offset=(start.getDay()+6)%7,s=stats();return `<div class="toolbar">${button('Mes anterior','month','data-step="-1"')}<strong>${start.toLocaleDateString('es-PA',{month:'long',year:'numeric'})}</strong>${button('Mes siguiente','month','data-step="1"')}</div><div class="calendar">${weekDays.map(d=>`<span class="muted">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:last},(_,i)=>{const d=`${month}-${String(i+1).padStart(2,'0')}`;return `<button class="day ${s.days.includes(d)?'trained':s.rest.has(d)?'rest':''} ${d===day()?'today':''}" data-action="day-detail" data-date="${d}" aria-label="${dateText(d)} ${s.days.includes(d)?'entrenamiento':s.rest.has(d)?'descanso':'sin registro'}">${i+1}</button>`;}).join('')}</div><p class="muted">Verde: entrenamiento · Lavanda: descanso</p>`;}
  function progress(){const weeks=new Map();for(const d of stats().days){const dt=new Date(d+'T12:00:00');dt.setDate(dt.getDate()-(dt.getDay()+6)%7);const key=day(dt);weeks.set(key,(weeks.get(key)||0)+1);}const weekly=[...weeks.entries()].sort((a,b)=>a[0].localeCompare(b[0]));const weights=state.weights.slice().sort((a,b)=>a.date.localeCompare(b.date));const avgs=weights.map(w=>{const end=new Date(w.date+'T12:00:00'),start=new Date(end);start.setDate(start.getDate()-6);const list=weights.filter(x=>x.date<=w.date&&x.date>=day(start));return [w.date,list.reduce((a,x)=>a+num(x.weightKg),0)/list.length];});const exerciseNames=[...new Set(state.sessions.flatMap(s=>s.exercises.filter(e=>e.type==='strength').map(e=>e.name)))];const chosen=state.config.chartExercise||exerciseNames[0],strength=state.sessions.flatMap(s=>{const sets=s.exercises.filter(e=>e.name===chosen).flatMap(e=>e.sets).filter(x=>x.completed&&x.type!=='W'&&x.reps>0&&x.reps<=10&&x.weightKg>0);return sets.length?[[s.date,Math.max(...sets.map(x=>x.weightKg*(x.reps===1?1:1+x.reps/30)))]]:[];}).sort((a,b)=>a[0].localeCompare(b[0]));return head('TU EVOLUCIÓN','Progreso, con contexto.','Tus datos cuentan la historia. No hay resultados físicos garantizados.')+`<div class="toolbar">${button('Registrar peso','weight','','primary')}${button('Chequeo semanal','checkin')}${button('Medidas / fotos','measure')}${button('Exportar historial','exports')}</div><div class="grid two"><section class="card"><h2>Promedio móvil de 7 días</h2>${chart(avgs,'Promedio móvil del peso en kilogramos')}<p class="source-note">Usa los pesajes disponibles de cada ventana; no se inventan los días sin registro.</p></section><section class="card"><h2>Días de entrenamiento</h2>${calendar()}</section></div><section class="card"><h2>Fuerza · 1RM estimado</h2><select aria-label="Ejercicio para gráfica" id="chart-exercise">${exerciseNames.map(x=>`<option ${x===chosen?'selected':''}>${esc(x)}</option>`).join('')}</select>${chart(strength,`1RM estimado ${chosen||''}`)}<p class="source-note">Epley, series de 1–10 reps. Es una estimación; no es una indicación de intentar ese peso.</p></section><section class="card"><h2>Entrenamientos por semana</h2>${chart(weekly,'Días entrenados por semana')}<p class="muted">Una fecha cuenta una sola vez, aunque hagas varias sesiones.</p></section><section class="card"><h2>Historial completo de sesiones</h2>${state.sessions.slice().reverse().map(s=>`<div class="list-row"><div><strong>${esc(s.routineName)}</strong><p class="muted">${dateText(s.date)} · ${fmt(metrics(s).volume)} kg de tonelaje</p></div>${button('Ver resumen','summary',`data-id="${s.id}"`)}</div>`).join('')||'<p class="empty">Tu primera sesión aparecerá aquí.</p>'}</section><section class="card"><h2>Peso y chequeos</h2>${weights.slice().reverse().map(w=>`<div class="list-row"><span>${dateText(w.date)}</span><strong>${fmt(w.weightKg,2)} kg</strong>${button('Corregir','weight',`data-date="${w.date}"`)}</div>`).join('')||'<p class="muted">Todavía no hay pesajes.</p>'}${state.checkins.slice().reverse().map(c=>`<p>${dateText(c.date)} · Calorías: ${c.calories?'sí':'no'} · Entrenamiento: ${c.training?'sí':'no'} · ${esc(c.notes)}</p>`).join('')}</section><section class="card"><h2>Medidas mensuales</h2>${state.measurements.map(m=>`<p>${dateText(m.date)} · Cintura ${m.waist||'—'} · Pecho ${m.chest||'—'} · Cadera ${m.hip||'—'} · Brazo ${m.arm||'—'} · Muslo ${m.thigh||'—'} cm</p>`).join('')||'<p class="muted">Registra medidas una vez al mes.</p>'}<div class="grid three">${state.photos.map(p=>`<figure class="media"><img data-media="${p.mediaId}" alt="Foto de progreso del ${esc(p.date)}"><figcaption>${dateText(p.date)}</figcaption></figure>`).join('')}</div></section>`;}
  function profile(){const p=state.profile,r=state.reminders;return head('TU PUNTO DE PARTIDA','Un plan que puedas ajustar.')+`<form id="profile-form" class="card"><h2>Perfil</h2><div class="form-grid">${field('Nombre','name',p.name||'','text','maxlength="60"')}${field('Edad','age',p.age,'number','required min="13" max="100"')}${select('Sexo para la fórmula','sex',p.sex||'male',[['male','Masculino'],['female','Femenino']])}${field('Altura (cm)','heightCm',p.heightCm,'number','required min="100" max="230" step="0.1"')}${field('Peso inicial (kg)','initialWeightKg',p.initialWeightKg,'number','required min="30" max="350" step="0.1"')}${select('Experiencia','experience',p.experience||'beginner',[['beginner','Principiante'],['intermediate','Intermedio'],['advanced','Avanzado']])}${field('Equipo disponible','equipment',p.equipment||'','text','placeholder="Mancuernas, banco, gimnasio…" maxlength="300"')}${select('Objetivo','goal',p.goal||'fat_loss',[['fat_loss','Perder grasa y conservar músculo'],['maintain','Mantener peso y músculo']])}${field('País','country',p.country||'','text','maxlength="60"')}${field('Presupuesto semanal de comida','foodBudget',p.foodBudget,'number','min="0" step="0.01"')}${field('Moneda','currency',p.currency||'USD','text','maxlength="8"')}${field('Factor de actividad','activityFactor',p.activityFactor||1.4,'number','required min="1" max="2.5" step="0.05"')}${field('Proteína (g/kg)','proteinPerKg',p.proteinPerKg||1.6,'number','required min="0.8" max="2.5" step="0.1"')}${field('Grasas (g/kg)','fatPerKg',p.fatPerKg||0.8,'number','required min="0.5" max="1.5" step="0.1"')}${field('Inicio del programa','programStart',p.programStart,'date','required')}${select('Descarga cada','deloadWeeks',p.deloadWeeks||6,[[5,'5 semanas'],[6,'6 semanas']])}${select('Pausa de dieta cada','dietBreakWeeks',p.dietBreakWeeks||9,[[8,'8 semanas'],[9,'9 semanas'],[10,'10 semanas']])}</div><p class="source-note">Factor orientativo: 1,2 poca actividad; 1,55 moderada; 1,725 alta. La estimación puede diferir de tus necesidades reales.</p>${actions('Guardar perfil')}</form><section class="card"><h2>Calorías y macros</h2><p>Recalcula manualmente con el promedio de tus últimos 7 días, o con el peso inicial si todavía no hay pesajes.</p>${button('Recalcular TDEE','calculate','','primary')}<p class="source-note">Fórmula Mifflin–St Jeor. Estimación para adultos; no personaliza situaciones de embarazo, lactancia o atención médica.</p></section><form id="reminders-form" class="card"><h2>Recordatorios</h2><div class="form-grid">${field('Hora para pesarte','weighTime',r.weighTime,'time','required')}${field('Hora de entrenamiento','trainingTime',r.trainingTime,'time','required')}${select('Día del chequeo','checkinDay',r.checkinDay,weekDays.map((x,i)=>[i+1,x]))}${field('Hora del chequeo','checkinTime',r.checkinTime,'time','required')}</div><p class="muted">Los días de entrenamiento siguen el split activo. Las notificaciones del navegador funcionan con la app abierta. Para avisos con la app cerrada, importa los recordatorios en el calendario de tu teléfono.</p><div class="toolbar"><button class="btn primary">Guardar horarios</button>${button('Activar avisos del navegador','notifications')}${button('Descargar calendario','calendar-export')}</div></form><section class="card"><h2>Tus datos</h2><p>Se guardan en este navegador. Las fotos y videos también permanecen en este dispositivo. Borrar los datos del navegador puede eliminarlos; guarda una copia de seguridad.</p>${button('Exportaciones y copia de seguridad','exports')}<p class="source-note">Esta versión es local: no sincroniza entre dispositivos y no simula una cuenta protegida por contraseña.</p></section>`;}
  function food(){return NUI.render();}
  function weightForm(d=day()){const w=state.weights.find(x=>x.date===d);modal('Registrar peso',`<form id="weight-form" class="form-grid">${field('Fecha','date',d,'date',`required max="${day()}"`)}${field('Peso (kg)','weightKg',w?.weightKg||'','number','required min="30" max="350" step="0.01"')}${actions('Guardar peso')}</form>`);}
  function checkinForm(){modal('Tu chequeo semanal',`<form id="checkin-form"><div class="form-grid">${field('Fecha del chequeo','date',day(),'date',`required max="${day()}"`)}${select('¿Cumpliste tus calorías esta semana?','calories','',[['','Selecciona'],['yes','Sí'],['no','No']])}${select('¿Cumpliste tus entrenamientos?','training','',[['','Selecciona'],['yes','Sí'],['no','No']])}<label class="wide">Sueño, energía y observaciones<textarea name="notes" maxlength="2000"></textarea></label></div>${actions('Guardar chequeo')}</form>`);$('#checkin-form [name=calories]').required=true;$('#checkin-form [name=training]').required=true;}
  function measureForm(){modal('Medidas y fotos',`<form id="measure-form"><p class="muted">Las medidas son opcionales; puedes añadir solo una foto. Se guardará en este dispositivo.</p><div class="form-grid">${field('Fecha','date',day(),'date',`required max="${day()}"`)}${[['Cintura','waist'],['Pecho','chest'],['Cadera','hip'],['Brazo','arm'],['Muslo','thigh']].map(([l,k])=>field(l+' (cm)',k,'','number','min="10" max="250" step="0.1"')).join('')}<label class="wide">Foto de progreso (hasta 20 MB)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label></div>${actions('Guardar registro')}</form>`);}
  function routineForm(rid){editingRoutine=clone(state.routines.find(r=>r.id===rid)||{id:id(),name:'',days:[1,3,5],exercises:[]});routineEditor();}
  function routineEditor(){const r=editingRoutine;modal('Tu rutina',`<form id="routine-form"><div class="form-grid">${field('Nombre de la rutina','name',r.name,'text','required maxlength="100"')}<div><p>Días de entrenamiento</p><div class="toolbar">${weekDays.map((d,i)=>`<label class="check-label"><input type="checkbox" name="days" value="${i+1}" ${r.days.includes(i+1)?'checked':''}>${d}</label>`).join('')}</div></div></div><div class="toolbar">${button('Agregar ejercicio propio','exercise-edit')}${button('Elegir ejercicio de la biblioteca','library')}</div>${r.exercises.map((e,i)=>`<div class="list-row"><div><strong>${esc(e.name)}</strong><p class="muted">${e.sets} series · ${e.repMin}–${e.repMax} ${e.type==='strength'?'reps':'s'} · ${esc(e.muscles)}${e.type==='strength'&&e.plannedWeightKg!=null?' · '+fmt(e.plannedWeightKg,2)+' kg planificados':''}</p></div><div>${button('Editar','exercise-edit',`data-index="${i}"`)}${button('Subir','exercise-up',`data-index="${i}"`)}${button('Quitar','exercise-remove',`data-index="${i}"`)}</div></div>`).join('')}${actions('Guardar rutina')}</form>`);}
  function rememberRoutine(){const f=$('#routine-form');if(f){editingRoutine.name=f.elements.name.value;editingRoutine.days=[...f.querySelectorAll('[name=days]:checked')].map(x=>+x.value);}}
  function exerciseForm(index){rememberRoutine();const e=editingRoutine.exercises[index]||{name:'',muscles:'',type:'strength',sets:3,repMin:8,repMax:12,restSeconds:90,incrementKg:2.5};modal('Configurar ejercicio',`<form id="exercise-form" data-index="${index??-1}"><div class="form-grid">${field('Nombre','name',e.name,'text','required maxlength="100"')}${field('Músculos trabajados','muscles',e.muscles,'text','required maxlength="200"')}${select('Modalidad','type',e.type,[['strength','Fuerza'],['isometric','Isométrico'],['cardio','Cardio']])}${field('Series','sets',e.sets,'number','required min="1" max="20"')}${field('Reps / segundos mínimos','repMin',e.repMin,'number','required min="1" max="3600"')}${field('Reps / segundos máximos','repMax',e.repMax,'number','required min="1" max="3600"')}${field('Descanso (segundos)','restSeconds',e.restSeconds,'number','required min="0" max="1800"')}${field('Carga planificada (kg)','plannedWeightKg',e.plannedWeightKg??'','number','min="0" max="1000" step="0.25" placeholder="Ej. 40"')}${field('Incremento de carga (kg)','incrementKg',e.incrementKg||2.5,'number','required min="0.25" max="20" step="0.25"')}<label class="wide">Técnica y notas<textarea name="notes" maxlength="3000">${esc(e.notes)}</textarea></label><label class="wide">Foto o video propio (hasta 20 MB)<input name="media" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></label>${field('O enlace HTTPS del video','videoUrl',e.videoUrl||'','url','maxlength="2000" placeholder="https://…"')}</div><p class="source-note">La carga planificada inicia tus series de fuerza; podrás cambiarla durante el entrenamiento. Vacía usa tu última carga normal registrada, y 0 significa sin carga externa. El incremento se usa para proponer subidas. Registra siempre la carga total con la misma convención.</p>${actions('Agregar a la rutina')}</form>`);}
  function supplementForm(sid){const s=state.supplements.find(s=>s.id===sid)||{};modal('Tu suplemento',`<form id="supplement-form" data-id="${esc(sid||'')}"><div class="form-grid">${field('Nombre','name',s.name||'','text','required maxlength="80"')}${field('Gramos que quedan','remainingGrams',s.remainingGrams,'number','required min="0" max="20000" step="0.1"')}${field('Tu consumo diario (g)','dailyGrams',s.dailyGrams,'number','required min="0" max="500" step="0.1"')}</div>${actions('Guardar envase')}</form>`);}
  let pendingCalculation,pendingDecision;
  function calculate(){const avg=weightAverage(),p={...state.profile};delete p.calorieTarget;const calc=C.calories(p,avg.value||p.initialWeightKg);if(!calc.valid)throw Error(calc.reason);pendingCalculation=calc;modal('Revisar calorías y macros',`<p>Calculado con ${fmt(calc.weightKg,2)} kg ${avg.count?'del promedio reciente':'del peso inicial'} y factor ${calc.activityFactor}.</p><div class="grid two">${metric(fmt(calc.ree),'kcal de gasto en reposo')}${metric(fmt(calc.tdee),'kcal de TDEE estimado')}${metric(fmt(calc.target),'kcal objetivo')}${metric(`${calc.proteinGrams} g`,'proteína')}</div><p>${calc.fatGrams} g grasa · ${calc.carbsGrams??'Por revisar'} g carbohidratos.</p><p class="source-note">${esc(calc.reason)} No garantiza un ritmo de cambio físico.</p>${calc.macrosValid?button('Aplicar este objetivo','apply-calories','','primary'):''}`);}
  function decision(){const result=C.decision(state,day());pendingDecision=result;modal('Revisión de tu tendencia',`<p>${esc(result.reason)}</p>${result.trend?metric(`${fmt(result.trend.lossPercentPerWeek,2)} %`,'pérdida semanal estimada')+'<p>'+dateText(result.trend.from)+' – '+dateText(result.trend.to)+' · '+result.trend.count+' pesajes</p>':''}${result.suggestedCalories?`<p>Objetivo sugerido: <strong>${fmt(result.suggestedCalories)} kcal</strong></p>${button('Aplicar sugerencia','apply-decision','','primary')}`:''}${result.recovery?.suggested?button('Planificar descarga','deload'):''}<p class="source-note">Reglas configuradas: menos de 0,35 % con buena adherencia, revisar una reducción; más de 1 %, revisar una subida. Al menos 14 días de datos y 14 días entre ajustes.</p>`);}
  function exports(){const datasets=IO.csvDatasets(state);modal('Tus datos, contigo',`<p>Descarga todo el historial o elige una tabla. La copia de seguridad incluye también las fotos y videos guardados.</p><div class="toolbar">${button('CSV completo','csv-all')}${button('Imprimir / guardar PDF','pdf')}${button('Copia de seguridad','backup')}</div><label>CSV por sección<select id="csv-section">${Object.keys(datasets).map(k=>`<option>${esc(k)}</option>`).join('')}</select></label>${button('Descargar tabla','csv-section')}<form id="restore-form"><h3>Restaurar una copia</h3><p class="muted">La copia reemplazará los registros de esta versión. Descarga primero una copia actual si quieres conservarlos.</p><input name="backup" type="file" accept="application/json,.json" required><label class="check-label"><input type="checkbox" name="confirm" required>Quiero reemplazar los datos con esta copia.</label>${actions('Restaurar copia')}</form>`);}
  async function loadMedia(){for(const el of document.querySelectorAll('[data-media]')){try{const u=await Store.mediaURL(el.dataset.media);if(u){mediaURLs.push(u);if(el.isConnected)el.src=u;}}catch{el.alt='No se pudo cargar este archivo.';}}}
  async function mediaFile(file){if(!file?.size)return null;if(file.size>20*1024*1024)throw Error('El archivo supera los 20 MB. Elige uno más pequeño.');const previewURL=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{const element=file.type.startsWith('video/')?document.createElement('video'):new Image();const done=(error)=>{clearTimeout(timeout);if(element.pause)element.pause();element.removeAttribute('src');error?reject(error):resolve();};const timeout=setTimeout(()=>done(Error('No se pudo leer el archivo. Prueba una imagen JPG/PNG o un video MP4/WebM.')),12000);element.onload=()=>done();element.onloadedmetadata=()=>done();element.onerror=()=>done(Error('Este archivo no se puede mostrar en el navegador. Prueba JPG/PNG o un video MP4 H.264/WebM.'));element.preload='metadata';element.src=previewURL;});}finally{URL.revokeObjectURL(previewURL);}return Store.putMedia(file);}
  function safeURL(v){if(!v)return '';const u=new URL(v);if(u.protocol!=='https:')throw Error('Usa un enlace HTTPS para el video.');return u.href;}
  function tick(){const a=state?.activeSession,now=Date.now();document.querySelectorAll('[data-session-clock]').forEach(el=>el.textContent=duration((now-a.startedAt)/1000));const rest=$('[data-rest-clock]');if(rest)rest.textContent=duration(a?.restUntil?(a.restUntil-now)/1000:0);document.querySelectorAll('[data-set-clock]').forEach(el=>{const [e,s]=el.dataset.setClock.split('|').map(Number),set=a.exercises[e].sets[s];el.textContent=duration((now-set.timerStartedAt)/1000+num(set.durationSeconds));});if(a?.restUntil&&now>=a.restUntil&&!a.restNotified){a.restNotified=true;notice('Tu descanso terminó. Continúa cuando estés listo.');save();}checkReminders();}
  function checkReminders(){if(!state?.reminders.enabled)return;const now=new Date(),time=now.toTimeString().slice(0,5),dow=(now.getDay()+6)%7+1,r=state.reminders,active=state.routines.find(x=>x.id===state.selectedRoutine),events=[['peso',r.weighTime,'Es hora de registrar tu peso'],['entreno',r.trainingTime,'Hoy tienes entrenamiento'],['chequeo',r.checkinTime,'Haz tu chequeo semanal']];for(const [key,hour,msg] of events){if(key==='entreno'&&!active?.days.includes(dow)||key==='chequeo'&&num(r.checkinDay)!==dow)continue;const tag=day()+key;if(time===hour&&!state.reminderSeen[tag]){state.reminderSeen[tag]=true;notice(msg);if(window.Notification?.permission==='granted')try{new Notification('Impulso',{body:msg});}catch{}save();}}}
  async function action(name,b){
    if(NUI.handlesAction(name))return NUI.action(name,b);
    const a=state.activeSession,ei=num(b.dataset.e),si=num(b.dataset.s),eid=b.dataset.id;
    if(name==='nav')return navigate(b.dataset.view);
    if(name==='weight')return weightForm(b.dataset.date);
    if(name==='checkin')return checkinForm();
    if(name==='measure')return measureForm();
    if(name==='routine')return routineForm(eid);
    if(name==='exercise-edit')return exerciseForm(b.dataset.index===undefined?undefined:+b.dataset.index);
    if(name==='library'){rememberRoutine();return modal('Biblioteca de ejercicios',`<div class="grid two">${[...FitnessSeeds.routines.flatMap(r=>r.exercises),...FitnessSeeds.exerciseLibrary].map((e,i)=>button(esc(e.name),'pick-exercise',`data-index="${i}"`)).join('')}</div>`);}
    if(name==='pick-exercise'){const e=[...FitnessSeeds.routines.flatMap(r=>r.exercises),...FitnessSeeds.exerciseLibrary][+b.dataset.index];editingRoutine.exercises.push(seedExercise(clone(e)));return routineEditor();}
    if(name==='exercise-remove'){rememberRoutine();editingRoutine.exercises.splice(+b.dataset.index,1);return routineEditor();}
    if(name==='exercise-up'){rememberRoutine();const i=+b.dataset.index;if(i>0)[editingRoutine.exercises[i-1],editingRoutine.exercises[i]]=[editingRoutine.exercises[i],editingRoutine.exercises[i-1]];return routineEditor();}
    if(name==='select'){state.selectedRoutine=eid;save();render();notice('Split activo actualizado.');return;}
    if(name==='start')return start(eid);
    if(name==='resume')return navigate('sesion');
    if(name==='add-set'){a.exercises[ei].sets.push(newSet(a.exercises[ei]));save();render();return;}
    if(name==='use-progression'){
      const e=a.exercises[ei],proposal=C.progression({...e,setsTarget:e.setsTarget},state.sessions);
      if(a.deload||e.type!=='strength'||proposal.suggestedWeightKg===null||!proposal.suggestedReps.length)throw Error('Todavía no hay una propuesta disponible.');
      let changed=0;e.sets.forEach((s,index)=>{if(s.type==='N'&&!s.completed){s.weightKg=proposal.suggestedWeightKg;s.reps=proposal.suggestedReps[index]??proposal.suggestedReps[0];changed++;}});
      if(!changed)throw Error('Todas las series normales ya están completadas.');
      const planned=state.routines.find(r=>r.id===a.routineId)?.exercises.find(x=>x.id===e.id);if(planned)planned.plannedWeightKg=proposal.suggestedWeightKg;
      e.plannedWeightKg=proposal.suggestedWeightKg;save();render();notice('Propuesta aplicada a las series pendientes y a la carga planificada de la rutina.');return;
    }
    if(name==='complete'){
      const e=a.exercises[ei],s=e.sets[si];
      const inputs=[...document.querySelectorAll('input[data-e="'+ei+'"][data-s="'+si+'"]')];if(!s.completed&&inputs.some(x=>!x.checkValidity()))throw Error('Revisa los valores de esta serie antes de marcarla.');
      if(!s.completed){if(s.timerStartedAt){s.durationSeconds=num(s.durationSeconds)+(Date.now()-s.timerStartedAt)/1000;delete s.timerStartedAt;}if(e.type==='strength'&&!(num(s.reps)>0))throw Error('Introduce las repeticiones antes de marcar esta serie.');if(e.type!=='strength'&&!(num(s.durationSeconds)>0))throw Error('Registra la duración antes de marcar esta serie.');if(a.restStartedAt){const previousSet=a.exercises.flatMap(x=>x.sets).find(x=>x.id===a.restSetId);if(previousSet)previousSet.actualRestSeconds=Math.round((Date.now()-a.restStartedAt)/1000);}s.completed=true;s.completedAt=Date.now();a.restStartedAt=Date.now();a.restUntil=Date.now()+num(s.restSeconds)*1000;a.restSetId=s.id;a.restNotified=false;}else{s.completed=false;if(a.restSetId===s.id){a.restUntil=null;a.restStartedAt=null;a.restSetId=null;}}
      save();render();return;
    }
    if(name==='set-timer'){const s=a.exercises[ei].sets[si];if(s.completed)throw Error('Desmarca la serie para modificar su duración.');if(s.timerStartedAt){s.durationSeconds=Math.round(num(s.durationSeconds)+(Date.now()-s.timerStartedAt)/1000);delete s.timerStartedAt;}else s.timerStartedAt=Date.now();save();render();return;}
    if(name==='rest-more'){if(a){a.restUntil=Math.max(a.restUntil||0,Date.now())+30000;a.restNotified=false;save();}return;}
    if(name==='rest-skip'){if(a?.restStartedAt){const s=a.exercises.flatMap(x=>x.sets).find(x=>x.id===a.restSetId);if(s)s.actualRestSeconds=Math.round((Date.now()-a.restStartedAt)/1000);a.restUntil=null;a.restStartedAt=null;a.restSetId=null;save();tick();}return;}
    if(name==='technique'){const e=a.exercises[ei];return modal(e.name,`<p class="eyebrow">${esc(e.muscles)}</p><p style="white-space:pre-line">${esc(e.notes||'Añade tus indicaciones de técnica al editar este ejercicio.')}</p>${e.mediaId?`<div class="media">${e.mediaType?.startsWith('video/')?`<video controls playsinline data-media="${e.mediaId}"></video>`:`<img data-media="${e.mediaId}" alt="Referencia de ${esc(e.name)}">`}</div>`:''}${e.videoUrl?`<p><a href="${esc(safeURL(e.videoUrl))}" target="_blank" rel="noopener noreferrer">Ver video de técnica</a></p>`:''}`);}
    if(name==='finish'){if(!a||!metrics(a).sets)throw Error('Completa al menos una serie para guardar la sesión.');if(a.exercises.some(e=>e.sets.some(s=>s.timerStartedAt)))throw Error('Detén los cronómetros de serie antes de finalizar.');const finished=clone({...a,status:'completed',finishedAt:Date.now()});if(!state.sessions.some(s=>s.id===finished.id))state.sessions.push(finished);state.activeSession=null;save();navigate('progreso');summary(finished);return;}
    if(name==='discard')return modal('Descartar esta sesión',`<p>Se quitarán solo las series de la sesión en curso. Las sesiones finalizadas se conservan.</p>${button('Descartar sesión actual','confirm-discard','','danger')}`);
    if(name==='confirm-discard'){state.activeSession=null;save();close();navigate('rutinas');return;}
    if(name==='summary')return summary(state.sessions.find(s=>s.id===eid));
    if(name==='show-history'){close();return navigate('progreso');}
    if(name==='month'){const d=new Date(`${month}-15T12:00:00`);d.setMonth(d.getMonth()+num(b.dataset.step));month=day(d).slice(0,7);return render();}
    if(name==='day-detail'){const d=b.dataset.date,sessions=state.sessions.filter(s=>s.date===d);return modal(dateText(d),sessions.map(s=>`<div class="list-row"><span>${esc(s.routineName)}</span>${button('Ver resumen','summary',`data-id="${s.id}"`)}</div>`).join('')+(stats().rest.has(d)?`<p>Descanso registrado.</p>${button('Quitar descanso','rest-remove',`data-date="${d}"`)}`:sessions.length?'':`<p>Sin entrenamiento registrado.</p>${d<=day()?button('Registrar como descanso','rest',`data-date="${d}"`):''}`));}
    if(name==='rest')return modal('Registrar día de descanso',`<form id="rest-form">${field('Fecha','date',b.dataset.date||day(),'date',`required max="${day()}"`)}<p>Protege la continuidad sin sumar un día entrenado.</p>${actions('Guardar descanso')}</form>`);
    if(name==='rest-remove'){state.restDays=state.restDays.filter(r=>(typeof r==='string'?r:r.date)!==b.dataset.date);save();close();render();return;}
    if(name==='supplement')return supplementForm(eid);
    if(name==='consume'){const s=state.supplements.find(x=>x.id===eid);if(s.logs?.some(l=>l.date===day()))throw Error('El consumo de hoy ya está registrado.');if(!s.dailyGrams)throw Error('Configura primero tu consumo diario.');if(s.remainingGrams<s.dailyGrams)throw Error('No quedan suficientes gramos para esta dosis. Actualiza el envase.');s.remainingGrams-=s.dailyGrams;s.logs||=[];s.logs.push({date:day(),grams:s.dailyGrams});save();render();notice('Consumo registrado.');return;}
    if(name==='calculate')return calculate();
    if(name==='apply-calories'){const c=pendingCalculation;if(!c)return;state.targets={calories:c.target,protein:c.proteinGrams,fat:c.fatGrams,carbs:c.carbsGrams,tdee:c.tdee,date:day(),weightKg:c.weightKg};state.profile.calorieTarget=c.target;state.lastAdjustmentAt=day();state.adjustments||=[];state.adjustments.push({date:day(),calories:c.target,reason:'Recálculo manual'});save();close();render();notice('Objetivo actualizado.');return;}
    if(name==='decision')return decision();
    if(name==='apply-decision'){const d=pendingDecision;if(!d?.suggestedCalories)return;const baseline=C.calories(state.profile,weightAverage().value||state.profile.initialWeightKg);state.targets||={calories:baseline.target,protein:baseline.proteinGrams,fat:baseline.fatGrams,carbs:baseline.carbsGrams,tdee:baseline.tdee};state.adjustments||=[];state.adjustments.push({date:day(),previous:state.targets?.calories,calories:d.suggestedCalories,reason:d.reason});state.profile.calorieTarget=d.suggestedCalories;state.targets.calories=d.suggestedCalories;state.targets.carbs=Math.max(0,Math.round((d.suggestedCalories-state.targets.protein*4-state.targets.fat*9)/4));state.lastAdjustmentAt=day();save();close();render();notice('Sugerencia aplicada y guardada en el historial.');return;}
    if(name==='end-break'){state.profile.dietPhase='normal';state.profile.dietBreakStart=null;state.targets.calories=state.profile.preBreakCalories;state.profile.calorieTarget=state.targets.calories;state.targets.carbs=Math.max(0,Math.round((state.targets.calories-state.targets.protein*4-state.targets.fat*9)/4));state.lastAdjustmentAt=day();save();render();return;}
    if(name==='deload'||name==='dietbreak'){return modal(name==='deload'?'Planificar descarga':'Planificar pausa de dieta',`<form id="recovery-form" data-kind="${name}">${field('Fecha de inicio','date',day(),'date','required')}${field('Duración (días)','days',7,'number','required min="3" max="14"')}<p>${name==='deload'?'Durante este período, las nuevas sesiones tendrán aproximadamente la mitad de series. Puedes modificarlo según tu recuperación.':'Durante este período se usará tu TDEE estimado como referencia de mantenimiento. Al terminar podrás retomar tu objetivo previo.'}</p>${actions('Programar período')}</form>`);}
    if(name==='calendar-export'){const r=state.routines.find(x=>x.id===state.selectedRoutine);IO.downloadCalendar({...state.reminders,trainingDays:r?.days||[]},day());notice('Importa el archivo en el calendario de tu teléfono.');return;}
    if(name==='notifications'){if(!('Notification'in window))throw Error('Este navegador no admite avisos. Usa el calendario.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Los avisos no están permitidos. Puedes usar el calendario.');state.reminders.enabled=true;save();notice('Avisos activados mientras Impulso esté abierto.');return;}
    if(name==='exports')return exports();
    if(name==='csv-all')return IO.downloadCSV(state);
    if(name==='csv-section'){const key=$('#csv-section').value;return IO.download(IO.csvDatasets(state)[key],key,'text/csv;charset=utf-8');}
    if(name==='pdf')return IO.printReport(state);
    if(name==='backup'){await IO.exportBackup(state);notice('Copia de seguridad preparada.');return;}
  }
  async function submit(form){const f=new FormData(form),v=Object.fromEntries(f),kind=form.id;
    if(NUI.handlesForm(kind))return NUI.submit(form);
    if(kind==='profile-form'){for(const key of ['age','heightCm','initialWeightKg','activityFactor','foodBudget','proteinPerKg','fatPerKg','deloadWeeks','dietBreakWeeks'])v[key]=num(v[key]);state.profile={...state.profile,...v};save();render();notice('Perfil guardado. Puedes recalcular tus objetivos cuando quieras.');return;}
    if(kind==='weight-form'){state.weights=state.weights.filter(w=>w.date!==v.date);state.weights.push({date:v.date,weightKg:num(v.weightKg)});}
    if(kind==='checkin-form'){state.checkins=state.checkins.filter(w=>w.date!==v.date);state.checkins.push({date:v.date,calories:v.calories==='yes',training:v.training==='yes',notes:v.notes});}
    if(kind==='measure-form'){const measurement={date:v.date};for(const k of ['waist','chest','hip','arm','thigh'])if(v[k])measurement[k]=num(v[k]);if(Object.keys(measurement).length===1&&!f.get('photo')?.size)throw Error('Agrega una medida o una foto.');const mediaId=await mediaFile(f.get('photo'));if(mediaId)state.photos.push({id:id(),date:v.date,mediaId});if(Object.keys(measurement).length>1){state.measurements=state.measurements.filter(m=>m.date!==v.date);state.measurements.push(measurement);}}
    if(kind==='rest-form'){if(stats().days.includes(v.date))throw Error('Ese día ya tiene un entrenamiento.');state.restDays=state.restDays.filter(r=>(typeof r==='string'?r:r.date)!==v.date);state.restDays.push({date:v.date});}
    if(kind==='routine-form'){rememberRoutine();if(!editingRoutine.days.length)throw Error('Elige al menos un día de entrenamiento.');if(!editingRoutine.exercises.length)throw Error('Agrega al menos un ejercicio.');state.routines=state.routines.filter(r=>r.id!==editingRoutine.id);state.routines.push(clone(editingRoutine));}
    if(kind==='exercise-form'){if(num(v.repMax)<num(v.repMin))throw Error('El máximo debe ser igual o mayor que el mínimo.');const index=+form.dataset.index,old=editingRoutine.exercises[index]||{},file=f.get('media'),mediaId=await mediaFile(file);const e={...old,id:old.id||id(),name:v.name,muscles:v.muscles,type:v.type,sets:num(v.sets),repMin:num(v.repMin),repMax:num(v.repMax),restSeconds:num(v.restSeconds),incrementKg:num(v.incrementKg),plannedWeightKg:v.plannedWeightKg===''?null:Number(v.plannedWeightKg),notes:v.notes,videoUrl:safeURL(v.videoUrl)};Plan.initialWeight(e,[]);if(mediaId){e.mediaId=mediaId;e.mediaType=file.type;}if(index>=0)editingRoutine.exercises[index]=e;else editingRoutine.exercises.push(e);routineEditor();return;}
    if(kind==='supplement-form'){const old=state.supplements.find(x=>x.id===form.dataset.id);const s={id:old?.id||id(),name:v.name,remainingGrams:num(v.remainingGrams),dailyGrams:num(v.dailyGrams),logs:old?.logs||[]};state.supplements=state.supplements.filter(x=>x.id!==s.id);state.supplements.push(s);}
    if(kind==='reminders-form'){state.reminders={...state.reminders,...v,checkinDay:num(v.checkinDay)};save();notice('Horarios guardados.');return;}
    if(kind==='recovery-form'){const end=new Date(v.date+'T12:00:00');end.setDate(end.getDate()+num(v.days));if(form.dataset.kind==='deload'){state.profile.lastDeload=v.date;state.profile.deloadStart=v.date;state.profile.deloadUntil=day(end);}else{if(!state.targets?.tdee)throw Error('Calcula tu TDEE primero.');state.profile.lastDietBreak=v.date;state.profile.dietBreakStart=v.date;state.profile.dietBreakUntil=day(end);state.profile.preBreakCalories=state.targets.calories;state.profile.dietPhase='scheduled_break';} }
    if(kind==='restore-form'){const restored=await IO.importBackup(f.get('backup'));Store.save(restored);state=restored;close();initialize();notice('Copia restaurada.');return;}
    updateRecovery();save();close();render();notice('Guardado.');
  }
  const NUI=new FitnessNutritionUI({getState:()=>state,day,esc,fmt,field,select,metric,head,button,actions,modal,close,save,renderApp:render,notice,id,dateText});
  document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-close'))return close();if(b.dataset.nav)return navigate(b.dataset.nav);if(b.dataset.action){b.disabled=true;await action(b.dataset.action,b);}}catch(e){notice(e.message||'No se pudo completar la acción.');}finally{b.disabled=false;}});
  document.addEventListener('submit',async ev=>{if(!ev.target.id?.endsWith('-form'))return;ev.preventDefault();const b=ev.submitter;if(b)b.disabled=true;try{await submit(ev.target);}catch(e){notice(e.message||'No se pudo guardar.');}finally{if(b)b.disabled=false;}});
  document.addEventListener('input',ev=>{const el=ev.target;try{NUI.input(el);if(el.dataset.set){const s=state.activeSession.exercises[+el.dataset.e].sets[+el.dataset.s];if(el.type==='number'&&!el.checkValidity())return;s[el.dataset.set]=el.type==='number'?(el.value===''?'':Number(el.value)):el.value;save();if(el.dataset.set==='type')render();}if(el.hasAttribute('data-session-notes')){state.activeSession.notes=el.value;save();}}catch(e){$('#save-status').textContent='Cambios sin guardar';notice(e.message);}});
  document.addEventListener('change',ev=>{NUI.change(ev.target);if(ev.target.id==='chart-exercise'){state.config.chartExercise=ev.target.value;save();render();}});
  $('#modal').addEventListener('close',()=>$('#modal').querySelectorAll('video').forEach(v=>v.pause()));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateRecovery();tick();}});
  window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==view)navigate(location.hash.slice(1));});
  try{initialize();setInterval(tick,1000);if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});}catch(error){$('#view').innerHTML=`${head('NO PUDIMOS ABRIR TUS DATOS','Necesitamos revisar el guardado.')}<section class="card"><p>${esc(error.message)}</p><p>Tus registros anteriores no se han borrado.</p><form id="restore-form"><input name="backup" type="file" accept=".json" required><label class="check-label"><input name="confirm" type="checkbox" required>Restaurar los datos desde esta copia.</label><button class="btn primary">Restaurar copia</button></form></section>`;console.error(error);}
})();


